// AutoDiag Pro — generic OBD-II codes built from code families (SAE J2012 numbering).
// Each family knows its sensor/actuator, how it is wired, where it sits and what values to expect,
// so every generated code gets real test steps. Hand-written entries in data.js always win over these.

const GEN = {};      // code → { en, he, severity, safe, desc, causes, steps, location }   (Hebrew details)
const GEN_EN = {};   // code → { desc, causes, steps, location }                             (English details)
const FAMILY = {};   // code → family id
const FAMILIES = {}; // family id → [codes]

function put(fam, code, he, en){
  GEN[code] = he; GEN_EN[code] = en;
  FAMILY[code] = fam; (FAMILIES[fam] = FAMILIES[fam] || []).push(code);
}
const P = n => "P" + String(n).padStart(4, "0");
const U = n => "U" + String(n).padStart(4, "0");

