for(const [c,en,he,loc] of MODS){
  put("ulost", U(c), { en:`Lost Communication With ${en}`, he:`אובדן תקשורת עם ${he}`, severity:"בינונית", safe:"כן, בזהירות",
    desc:`מודול אחר ברשת לא מקבל הודעות מ${he}. המודול כבוי, לא מקבל מתח, או שיש בעיה בקווי ה-CAN אליו.`,
    causes:["מצבר חלש / מתח נמוך","נתיך או הזנה של המודול","אדמת המודול","קווי CAN אל המודול (קצר / פתוח / מחבר)","המודול עצמו תקול","חדירת מים למחבר"],
    steps:["בדוק מתח מצבר (מעל 12.4V) — מתח נמוך גורם להרבה קודי U","בדוק נתיכי הזנה של המודול והגעת 12V קבוע + הצתה","בדוק אדמת המודול (מפל מתח פחות מ-0.1V)","מדוד CAN בשקע OBD: ‏60Ω בין 6 ל-14 (מצבר מנותק)","מדוד CAN-H/CAN-L במחבר המודול (‎≈2.6V / ≈2.4V)","בדוק אם המודול מגיב בסורק מתקדם"], location:`${loc}.` },
    { desc:`Another module on the network is not receiving messages from the ${en}. The module is off, has no power, or its CAN lines are faulty.`,
      causes:["Weak battery / low voltage","Module fuse or supply","Module ground","CAN lines to the module (short / open / connector)","The module itself","Water in the connector"],
      steps:["Check battery voltage (above 12.4V) — low voltage causes many U codes","Check the module fuses and that it gets permanent 12V + ignition","Check the module ground (voltage drop below 0.1V)","Measure CAN at the OBD socket: 60Ω between 6 and 14 (battery off)","Measure CAN-H/CAN-L at the module connector (≈2.6V / ≈2.4V)","Check whether the module responds on an advanced scan tool"], location:"Location varies by vehicle." });
}

